insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4cbdb881-da9c-47a5-bedb-19e0456a3896', 'de', 'Wann wirkt Berührung gut und nicht aufdringlich?', '["Wenn sie zu ihrem Wohlgefühl und eurer Verbindung passt", "Wenn sie kurz und leicht ist, nicht lang oder schwer", "In natürlichen Momenten, etwa beim Lachen oder wenn du etwas betonst", "Alle oben genannten"]'::jsonb, 'Berührung fühlt sich gut an, wenn sie zur Verbindung passt, leicht bleibt und in natürlichen Momenten passiert.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4f400953-0471-468b-911c-2009c87a96ac', 'de', 'Das Gespräch macht Spaß, und sie lacht. Dann geht sie ganz natürlich. Was solltest du denken?', '["Das ist gescheitert, weil ich ihre Nummer nicht bekommen hab", "Das war zu kurz, ich hab versagt", "Das war ein Erfolg, weil wir beide den Moment genossen haben"]'::jsonb, 'Ein schöner gemeinsamer Moment ist das Ziel, egal ob noch mehr daraus wird.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('50183c21-27bd-480c-971a-891eac026c00', 'de', 'Sie sagt: „Männer geben mir immer Drinks aus.“ Mit welchem Satz könntest du sie disqualifizieren?', '["„Nur wenn du die nächste Runde holst.“", "„Dann lass mich dir einen holen.“", "„Klar, du bist ja auch charmant.“", "„Was ist dein Lieblingsdrink?“"]'::jsonb, 'Eine verspielte Herausforderung statt automatischer Zustimmung hält es ausgewogen und lustig.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('51566fba-0f2e-472b-9786-baa55e298382', 'de', 'Wann wirkt Berührung natürlich statt aufdringlich?', '["Wenn sie oft wiederholt wird", "Wenn sie in emotional warmen Momenten passiert", "Wenn sie kurz und leicht ist", "Wenn sie zu ihrem Wohlgefühl passt"]'::jsonb, 'Zu oft und zu viel überfordert. Timing und Feingefühl schaffen Leichtigkeit.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('51c9bf97-c01a-4148-8ca9-32bec583870d', 'de', 'Sie sagt: „Ich erwisch immer die falsche Schlange.“ Was könntest du darauf sagen?', '["„Ja, das passiert jedem.“", "„Warum glaubst du das?“", "„Die hier ist auch langsam.“", "„Du bist eindeutig verflucht. Bleib bei mir, ich bring Glück.“"]'::jsonb, 'Warme Übertreibung bringt etwas Frechheit und einen verspielten Rhythmus.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('530e8449-212d-45aa-8e97-70907690cac7', 'de', 'Wie bringst du etwas flirtend rüber?', '["Langsameres Tempo, nicht gehetzt", "Beim Sprechen Blickkontakt halten", "Die Worte mit einer kleinen Pause wirken lassen", "Alle oben genannten"]'::jsonb, 'Flirten lebt von Tempo und Präsenz. Werd langsamer, halt Blickkontakt und lass die Worte wirken.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('545da6d1-d1bc-41b2-90a4-6fb6c5a2003c', 'de', 'Was bedeutet „Blickkontakt“ beim Flirten?', '["Das ganze Gespräch über guten Blickkontakt halten", "Ein bewusster Blick, der Spannung erzeugt und Interesse zeigt", "Ihr tief in die Augen schauen, um Selbstbewusstsein zu zeigen"]'::jsonb, 'Blickkontakt beim Flirten zeigt Interesse durch Präsenz, nicht durch Dominanz oder Übertreibung.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('56839c41-b051-44d1-8c8b-3c1fc53a0809', 'de', 'Sie erklärt dir ein kompliziertes Thema. Welches Kompliment kommt am besten an?', '["„Das hast du richtig gut erklärt, man konnte super folgen.“", "„Du bist wirklich wunderschön.“", "„Du wirkst klug.“", "„Deine Stimme klingt richtig schön.“"]'::jsonb, 'Konkret auf ihre Art und Mühe bezogen. Das zeigt, dass du wirklich gesehen hast, wie sie es gemacht hat.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('57ea4716-3a0a-4ae1-9b73-029195409a88', 'de', 'Du kommst einen kleinen Schritt näher, und sie bleibt im Gespräch. Was zeigt das?', '["Grünes Licht: Der geringere Abstand ist ihr angenehm", "Sie will sofort mehr Abstand", "Du solltest zurücktreten, um auf Nummer sicher zu gehen", "Es ist noch zu früh im Gespräch"]'::jsonb, 'Wenn sie bleibt oder es erwidert, ist ihr die größere Nähe angenehm.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6021e5f1-ba61-4cb2-82c5-d1977fcb9ef6', 'de', 'Sie ist entspannt und spricht leise in einem ruhigen Café. Wie sollte deine Energie sein?', '["Entspannt und ruhig, mit warmem Ton", "Hoch und lebhaft, um sie mitzureißen", "Matt und müde, um lässig zu wirken", "Laut, um gegen die Geräusche anzukommen"]'::jsonb, 'Pass dich ihrer entspannten Stimmung an, dann fühlt ihr euch beide wohl und seid aufeinander eingestimmt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('634ce3b6-9096-4656-87e7-87d80d609efd', 'de', 'Sie schafft einen Moment, indem sie dir tief in die Augen schaut. Was zeigt es, wenn du den Blick hältst?', '["Bewusstes Interesse und den Wunsch, die Dynamik zu verändern", "Dass du nur höflich bist", "Nervosität und Unbehagen"]'::jsonb, 'Ein ruhiger Blick zeigt ohne Worte romantisches Interesse.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('63ef4906-b21c-4006-a7c2-c6651684dc24', 'de', 'Wann kommt ein Kompliment an, und wann verpufft es?', '["Konkret, echt und auf etwas bezogen, das sie selbst gewählt hat", "Es geht um besondere Eigenschaften, die sie von anderen abheben", "Aufrichtig und von Herzen, ohne Hintergedanken", "Alle oben genannten"]'::jsonb, 'Komplimente kommen an, wenn sie konkret und echt sind und sich auf etwas beziehen, das sie selbst gewählt hat.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('645db147-5379-46df-8e63-f2d46db760eb', 'de', 'Sie lacht herzlich und lehnt sich im Gespräch zu dir. Was könntest du als Nächstes tun?', '["Die Hände in den Taschen lassen, um auf Nummer sicher zu gehen", "Lächelnd kurz und leicht ihren Unterarm berühren", "Sie sofort umarmen, um weiterzugehen", "Ihr die Hand an den unteren Rücken legen, um sie zu führen"]'::jsonb, 'Eine kurze, leichte Berührung, wenn sie voll dabei ist, verstärkt ganz natürlich die Chemie.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6581dc47-ce07-4d7a-a3fb-126a6b812a79', 'de', 'Warum ist Wärme wichtig, wenn du frech bist?', '["Durch Wärme fühlt sich Frechsein nicht wie echte Unhöflichkeit an", "Sie macht Worte klarer, damit Witze richtig verstanden werden", "Wärme hilft, sich besser an Gespräche zu erinnern"]'::jsonb, 'Wärme macht freche Bemerkungen zum Spiel. Ohne sie können dieselben Worte unhöflich wirken.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('67aef6c5-f235-4eb5-ad2b-86fb824c4b0a', 'de', 'Dir fällt im Gespräch ihr besonderer Stil auf. Wie machst du am besten ein Kompliment?', '["Schnell „Cooler Stil!“ sagen und weitermachen", "Stärkere Worte benutzen", "Ein allgemeines Kompliment ohne Blickkontakt machen", "Mit weicher Stimme und Blickkontakt sagen: „Dein Stil sticht echt heraus.“"]'::jsonb, 'Bewusst und mit Wärme gesagt, baut ein Kompliment mehr Anziehung auf als höflich und schnell.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('69e57da2-5fe8-46fa-b9e1-c7e7f7579196', 'de', 'Was ist der eigentliche Zweck, beim Flirten die Nähe anzupassen?', '["Dominanz zeigen", "Die Anziehung so schnell wie möglich steigern", "Ihre Grenzen testen", "Den körperlichen Abstand dem emotionalen Wohlgefühl anpassen"]'::jsonb, 'Nähe wirkt, wenn sie dem emotionalen Wohlgefühl entspricht, nicht wenn sie drängt oder Grenzen testet.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6a0ee7f4-bdfd-47a6-901c-adfd7c6f56fa', 'de', 'Sie macht im Gespräch ganz mühelos Witze. Welches Kompliment passt?', '["„Du bist zum Brüllen, du solltest Comedy machen.“", "„Für eine Frau bist du echt lustig.“", "„Ich mag deinen Humor, der ist echt besonders.“"]'::jsonb, 'Die beste Antwort greift die Leichtigkeit des Moments auf, statt sie zu übersteigern.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('71303602-cef7-48f0-9a80-8ba290228313', 'de', 'Was bewirkt längerer Blickkontakt?', '["Er erzeugt eine Spannung zwischen euch, die über Worte hinausgeht", "Er zeigt Interesse, ohne es auszusprechen", "Er zeigt soziales Selbstbewusstsein"]'::jsonb, 'Blickkontakt zeigt Interesse ohne Worte, ohne eine Antwort zu erzwingen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('731d74c4-4ac6-43b0-bdcf-69cb8db3d00d', 'de', 'Sie sagt: „Ich bin wahrscheinlich viel zu oft hier.“ Was könntest du darauf sagen?', '["„Dann sollten sie langsam einen Drink nach dir benennen.“", "„Ist ja auch ein toller Laden.“", "„Das geht doch gar nicht.“", "„Wie oft kommst du denn?“"]'::jsonb, 'Verspielte Übertreibung mit Wärme macht den Moment unvergesslich.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('76d8660f-5734-4d14-9168-b2bd84bfeedf', 'de', 'Wann ist der beste Moment für ein Kompliment?', '["Als Allererstes", "Direkt bevor du nach ihrer Nummer fragst", "Ganz natürlich, nachdem sie etwas von sich gezeigt hat", "Nur wenn sie dir zuerst ein Kompliment macht"]'::jsonb, 'Komplimente kommen am besten an, wenn sie sich ganz natürlich aus dem Gespräch ergeben.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('78f2a3a1-b8f1-4d88-9854-152a0b2895ec', 'de', 'Sie erzählt, dass sie bei Brettspielen total ehrgeizig ist. Was ist eine lustige Antwort?', '["„Wettbewerb kann ungesund sein.“", "„Ich nehm Gewinnen sehr ernst.“", "„Aber wirf nicht den Tisch um, wenn ich gewinne.“", "„Brettspiele machen Spaß.“"]'::jsonb, 'Leichte Übertreibung hält es verspielt und bringt das Gespräch voran.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('79b0dd38-20dd-41fe-91af-1e353ef1dd35', 'de', 'Sie hat eine Geschichte zu Ende erzählt und schaut dich erwartungsvoll an. Was könnte knisternde Spannung erzeugen?', '["Schnell „Tolle Geschichte“ sagen und noch eine Frage stellen", "Sofort ihre Intelligenz loben", "Wegschauen und das Thema wechseln", "Den Blickkontakt länger halten, langsam lächeln und leise sagen: „Das hast du richtig schön erzählt.“"]'::jsonb, 'Ein längerer Blick und ein warmer Ton deuten eine Möglichkeit an, ohne Druck zu machen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7a679b53-6378-4e35-9329-c81feb6dbfcb', 'de', 'Du berührst leicht ihren Arm, und sie tritt zurück. Was solltest du tun?', '["Sofort aufhören und ihr Raum lassen", "Fragen, ob das für sie okay ist", "Davon ausgehen, dass sie sich nur ziert"]'::jsonb, 'Hör sofort auf und respektier ihre körperlichen Grenzen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7c711059-22dd-4139-9523-2de1103e125a', 'de', 'Was heißt es, deine Energie fein abzustimmen?', '["Immer viel Begeisterung mitbringen", "Genau spiegeln, ohne jede Abweichung", "Überall dieselbe Stimmung mitbringen", "Dich der Stimmung anpassen oder sie leicht anheben"]'::jsonb, 'Pass dich erst der Energie an, die da ist, und heb sie dann leicht an, wenn der Moment es zulässt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('897a30cf-cd54-4901-b729-6b351f07085b', 'de', 'Sie sagt: „Ich kann mich echt schlecht entscheiden.“ Wie kannst du frech reagieren?', '["„Ist okay, keiner ist perfekt.“", "„Was hilft dir normalerweise beim Entscheiden?“", "„Nimm einfach irgendwas, passt schon.“", "„Hast du dann etwa Angst vor der Speisekarte?“"]'::jsonb, 'Leichte, freche Übertreibung lädt zum Lachen und zu einer verspielten Antwort ein.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8b46401f-6a8e-4626-a152-9b226dc2e7bf', 'de', 'Du spürst eine gute Stimmung, zögerst aber. Welches Risiko gehst du ein, wenn du zu lange wartest?', '["Sie denkt vielleicht, dass du kein Interesse hast", "Das Gespräch bleibt höflich und neutral", "Das natürliche Zeitfenster für Spannung geht vorbei", "Alle oben genannten"]'::jsonb, 'Solche Momente haben ein Verfallsdatum. Das Zeitfenster ist klein, aber wichtig.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8fbef46b-8fef-4c0e-a566-41439198e3e7', 'de', 'Sie lehnt sich beim Lachen leicht zu dir. Was könntest du tun?', '["Starr beim ursprünglichen Abstand bleiben", "Den Abstand nach und nach verringern, passend zu ihrer Energie", "Zurücktreten, um ihr Raum zu geben", "Sofort ganz nah herangehen"]'::jsonb, 'Erwidere ihr Zeichen von Wohlgefühl, um den Moment ganz natürlich zu vertiefen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8fde0458-59d3-43bb-9001-d87062672d85', 'de', 'Welche Variante erzeugt mit denselben Worten eher romantische Spannung?', '["„Du bist echt witzig“, schnell gesagt und gleich zum nächsten Thema", "„Du bist echt witzig“, während du jemand anderen anschaust", "„Du bist echt witzig“, langsam gesagt, mit warmem Blickkontakt und einer Pause"]'::jsonb, 'Bewusstes Tempo und Präsenz laden den Satz auf, statt ihn nur höflich wirken zu lassen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('91ff2d3a-7637-491a-b8c0-a33a6b25a5bd', 'de', 'Was bedeutet „Berührung“ beim Flirten?', '["Körperkontakt, um Selbstbewusstsein und Absicht zu zeigen", "Bewusster, fein abgestimmter leichter Kontakt, der Wohlgefühl und Anziehung aufbaut", "Vom Reden zum Körperlichen übergehen, um Interesse zu zeigen"]'::jsonb, 'Berührung wirkt, wenn sie natürlich und fein abgestimmt ist und Leichtigkeit schafft statt Druck.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9307f2f7-e573-4a52-81e2-e255d0fe0983', 'de', 'Ein Drei-Minuten-Gespräch endet mit Lachen, aber ohne Nummer. Wie solltest du das sehen?', '["Als gelungenen, schönen Moment", "Als komplettes Versagen", "Als verpasste Chance auf einen Abschluss", "Als verschwendete Zeit"]'::jsonb, 'Das Ziel ist die schöne gemeinsame Energie, nicht das, was danach vielleicht kommt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('94b2a1ba-b2aa-42e8-bf7a-d35951d81430', 'de', 'Du gehst in der Bar auf eine ausgelassene Gruppe zu. Welche Energie passt?', '["Ruhige, entspannte Energie mitbringen, als Ausgleich zu ihrer Lautstärke", "Ihre lebhafte Energie mit einem fröhlichen Ton aufgreifen", "Etwas mehr Energie als sie mitbringen, um positiv aufzufallen"]'::jsonb, 'Menschen reagieren am besten auf fröhliche Energie, die zu ihrem Rhythmus passt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('95247c9b-621b-4050-bfa2-a28902ab1b90', 'de', 'Warum bauen kleine Herausforderungen schneller Chemie auf als normales Reden?', '["Sie erzeugen etwas Spannung, und sie bringt sich ein", "Aus Fremden werden kurzzeitig Rivalen oder ein Team", "Sie muss aktiv mitmachen", "Alle oben genannten"]'::jsonb, 'Wenn spielerisch etwas auf dem Spiel steht, entstehen Energie und Beteiligung, ohne echten Druck.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a1c414f9-7ab4-4475-a07e-69d6eb6b1ba4', 'de', 'Sie scherzt darüber, dass sie gern Schach spielt. Was wäre eine flirtende Antwort?', '["„Schach ist so anspruchsvoll.“", "„Schach ist so ein einfacher Sport.“", "„Wettbewerb ist ungesund.“", "„Gut, dass ich weiß, wie man seine Dame beschützt.“"]'::jsonb, 'Greif ihre Verspieltheit auf, um Schlagabtausch und Energie zu steigern.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a25d7cd3-3b21-4ccb-89ba-1cffbbe6a49d', 'de', 'Warum hilft Schlagabtausch, romantische Chemie aufzubauen?', '["Er schafft lockere Spannung und Verspieltheit", "Er verringert durch Lachen die emotionale Distanz", "Er hält das Gespräch ernst und höflich", "Er bringt ein gegenseitiges Hin und Her"]'::jsonb, 'Verspieltheit unterscheidet einen Flirt von einer bloß freundschaftlichen Verbindung.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a2f4b225-b8a7-4317-8f9e-d5d7ce3e0c73', 'de', 'Welches Verhalten zeigt respektvolle Aufmerksamkeit?', '["Weiterreden, um sie umzustimmen", "„Ich hab einen Freund“ akzeptieren, ohne nachzubohren", "Dich zurücknehmen, wenn sie knapp antwortet", "Das Gespräch höflich beenden, wenn sie kaum dabei ist"]'::jsonb, 'Respekt zeigt sich darin, wie schnell du dich anpasst und wie sauber du gehst, wenn kein Interesse da ist.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a621c77a-69b0-4f0a-8e2f-6e12dbf8bc0b', 'de', 'Warum erzeugt Disqualifizieren Anziehung?', '["Es zeigt, dass du ihrer Bestätigung hinterherläufst", "Es durchbricht das Muster automatischer Zustimmung", "Es behandelt sie als ebenbürtig, statt sie auf ein Podest zu stellen"]'::jsonb, 'Disqualifizieren macht aus einseitigem Werben ein ausgewogenes, gegenseitiges Auswählen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a64d80aa-89d6-4008-bb0c-2e3f3d44e8d8', 'de', 'Was erzeugt den „Funken“ knisternder Spannung?', '["Eine leise Ungewissheit, ob es mehr als platonisch ist", "Alles vorhersehbar und freundschaftlich halten", "Früh ausdrücklich romantische Absichten erklären", "Jede körperliche Wahrnehmung vermeiden"]'::jsonb, 'Die Frage „Ist das hier mehr?“ hält die Aufmerksamkeit wach.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
